import sys

data = sys.stdin.read().split()
n = int(data[0])
a = [int(data[1 + i]) for i in range(n)]
cover = []
for i, v in enumerate(a):
    m = 0
    if v > 0:
        for p in range(max(0, i - v), min(n - 1, i + v) + 1):
            m |= 1 << p
    cover.append(m)
full = (1 << n) - 1
best = -1
for mask in range(1 << n):
    c = 0
    for i in range(n):
        if mask >> i & 1:
            c |= cover[i]
    if c == full:
        k = bin(mask).count('1')
        if best == -1 or k < best:
            best = k
print(best)

